// A single Firestore :commit incremented both counters in one atomic step,
// so these are the authoritative post-increment values - two requests at the
// same moment can no longer read the same count and overwrite each other.
const keys = $node["Compute Quota Keys"].json;
const results = $json.writeResults || [];

function countFrom(result) {
  const transforms = (result && result.transformResults) || [];
  return Number((transforms[0] && transforms[0].integerValue) || 0);
}

return [{
  json: Object.assign({}, keys, {
    ipCount: countFrom(results[0]),
    totalCount: countFrom(results[1]),
  })
}];

