// The slot was reserved before the limit was known and has just been
// released again, so the stored counts are one below the values below.
const counts = $node["Parse Quota Reservation"].json;
const ipCount = counts.ipCount - 1;
const totalCount = counts.totalCount - 1;
const ipExceeded = counts.ipCount > 3;
const message = ipExceeded
  ? "You've reached today's limit of 3 recipe generations for your network. Please try again tomorrow."
  : "All daily recipe generations have been used up across all users. Please try again tomorrow.";

return [{
  json: {
    error: 'quota_exceeded',
    message: message,
    quota: {
      ipRemaining: Math.max(0, 3 - ipCount),
      totalRemaining: Math.max(0, 12 - totalCount),
    }
  }
}];

/*
 * Builds the user message for the "OpenAI: Generate Recipes" chain.
 *
 * The answer's JSON schema now lives in the "Recipe Output Parser" sub-node
 * and the model in the "OpenAI Chat Model" sub-node, so nothing here builds an
 * API request any more: this node only turns the validated options into the
 * compact JSON the prompt asks the model to work from.
 */
const options = $node["Validate Request Payload"].json.body;

const TIME_HINTS = {
  quick: "15 to 20 minutes",
  medium: "25 to 45 minutes",
  elaborate: "50 to 75 minutes"
};

const DIET_HINTS = {
  none: "no dietary restriction",
  vegetarian: "strictly vegetarian: no meat, no fish, no gelatine",
  vegan: "strictly vegan: no meat, fish, dairy, egg, honey or gelatine",
  keto: "ketogenic: very low carbohydrate, no pasta, rice, potatoes, bread or sugar"
};

const request = {
  servings: options.servings,
  cooks: options.helpers,
  cuisineStyle: options.cuisineStyle,
  diet: options.diet,
  dietRule: DIET_HINTS[options.diet] || DIET_HINTS.none,
  cookingTime: TIME_HINTS[options.timeCategory] || TIME_HINTS.medium,
  ingredientsAtHome: options.ingredients
};

return [{
  json: {
    promptRequest: JSON.stringify(request)
  }
}];

