/*
 * Turns the parsed answer into exactly the shape the app and the Firestore
 * rules expect. The "Recipe Output Parser" sub-node already guarantees the
 * field names and types (and has thrown the run into the fallback if the model
 * answered with prose), so what is left to do here is
 *   - unwrap the parser's result: a Structured Output Parser hands its data
 *     back under an "output" key, i.e. { output: { recipes: [...] } },
 *   - repair what a model may still get wrong (too many steps, a cook number
 *     that does not exist),
 *   - enforce the caps from firestore.rules, so a generated recipe can never
 *     be rejected when the app saves it to the library,
 *   - throw when the answer is unusable, which sends the run down the error
 *     output into "Generate Fallback Recipes".
 */
const options = $node["Validate Request Payload"].json.body;
const counts = $node["Parse Quota Reservation"].json;

const DIFFICULTIES = ["easy", "medium", "hard"];
const CUISINES = ["german", "italian", "japanese", "indian", "gourmet", "fusion"];

function text(value, max) {
  const cleaned = String(value == null ? "" : value).replace(/\s+/g, " ").trim();
  return cleaned.length > max ? cleaned.slice(0, max - 1).trim() + "…" : cleaned;
}

function whole(value, min, max, fallback) {
  const number = Math.round(Number(value));
  if (!Number.isFinite(number)) return fallback;
  return Math.min(max, Math.max(min, number));
}

function cook(value, position) {
  const number = Math.round(Number(value));
  const valid = Number.isFinite(number) && number >= 1 && number <= options.helpers;
  return valid ? number : (position % options.helpers) + 1;
}

function list(value, max, maxLength) {
  if (!Array.isArray(value)) return [];
  const items = [];
  for (const entry of value) {
    const line = text(entry, maxLength);
    if (line) items.push(line);
    if (items.length >= max) break;
  }
  return items;
}

/* The parser wraps its result in "output"; older/plain answers are accepted
   unwrapped too, so a change of parser version cannot break this node. */
const answer = $json && typeof $json === "object" ? $json : {};
const unwrapped = answer.output && typeof answer.output === "object" ? answer.output : answer;
const candidates = Array.isArray(unwrapped.recipes)
  ? unwrapped.recipes
  : (Array.isArray(unwrapped) ? unwrapped : []);

if (candidates.length < 3) throw new Error("The model returned " + candidates.length + " recipes instead of 3");

const recipes = candidates.slice(0, 3).map(function (recipe, index) {
  const steps = (Array.isArray(recipe.steps) ? recipe.steps : []).slice(0, 30).map(function (step, position) {
    return {
      instruction: text(step && step.instruction, 300),
      /* A cook number the user does not have is not clamped but replaced by
         the next cook in turn - clamping would push every stray step onto the
         last cook and leave the first one with nothing to do. */
      assignedTo: cook(step && step.assignedTo, position),
      isParallel: options.helpers > 1 && Boolean(step && step.isParallel)
    };
  }).filter(function (step) { return step.instruction.length > 0; });

  if (!steps.length) throw new Error("Recipe " + (index + 1) + " has no usable steps");

  const nutrition = recipe.nutrition || {};
  return {
    title: text(recipe.title, 200) || "Recipe " + (index + 1),
    description: text(recipe.description, 1000) || null,
    ingredients: list(recipe.ingredients, 50, 200),
    missingIngredients: list(recipe.missingIngredients, 20, 200),
    steps: steps,
    difficulty: DIFFICULTIES.indexOf(recipe.difficulty) === -1 ? "medium" : recipe.difficulty,
    cookingTimeMinutes: whole(recipe.cookingTimeMinutes, 1, 600, 30),
    /* Servings and cuisine are the user's choice, not the model's. */
    servings: options.servings,
    cuisineStyle: CUISINES.indexOf(options.cuisineStyle) === -1 ? "german" : options.cuisineStyle,
    nutrition: {
      caloriesPerServing: whole(nutrition.caloriesPerServing, 0, 5000, 0),
      proteinGrams: whole(nutrition.proteinGrams, 0, 500, 0),
      fatGrams: whole(nutrition.fatGrams, 0, 500, 0),
      carbsGrams: whole(nutrition.carbsGrams, 0, 500, 0)
    }
  };
});

for (const recipe of recipes) {
  if (!recipe.ingredients.length) throw new Error("A recipe came back without ingredients");
}

return [{
  json: {
    recipes: recipes,
    quota: {
      ipRemaining: Math.max(0, 3 - counts.ipCount),
      totalRemaining: Math.max(0, 12 - counts.totalCount)
    }
  }
}];

const CUISINE_PRESETS = {
  german: { nameTemplates: ["%s Pan, Home-Style", "Hearty %s Stew", "%s Bake"], spices: ["Marjoram", "Caraway", "Mustard", "Parsley"], staples: ["Butter", "Flour", "Cream", "Bacon"] },
  italian: { nameTemplates: ["Pasta al %s", "%s Risotto", "Oven-Baked %s alla Italiana"], spices: ["Basil", "Oregano", "Garlic", "Chili flakes"], staples: ["Olive oil", "Parmesan", "Pasta", "Tomato passata"] },
  japanese: { nameTemplates: ["%s Teriyaki Pan", "%s Donburi", "Miso Soup with %s"], spices: ["Soy sauce", "Ginger", "Sesame", "Mirin"], staples: ["Rice", "Soy sauce", "Sesame oil", "Nori"] },
  indian: { nameTemplates: ["%s Curry", "%s Masala Pan", "Spicy %s Dal"], spices: ["Turmeric", "Garam masala", "Cumin", "Coriander"], staples: ["Basmati rice", "Coconut milk", "Lentils", "Ghee"] },
  gourmet: { nameTemplates: ["%s Finely Poached with Beurre Blanc", "Confit %s Composition", "%s Fine-Dining Plate"], spices: ["Thyme", "Sea salt", "Butter", "White wine"], staples: ["Butter", "Cream", "White wine", "Shallots"] },
  fusion: { nameTemplates: ["%s Fusion Bowl", "Street Food Wrap with %s", "Pan-Seared %s Fusion-Style"], spices: ["Soy sauce", "Lime", "Chili", "Coriander"], staples: ["Soy sauce", "Lime", "Sesame oil", "Spring onions"] }
};
const DIET_EXCLUDED_STAPLES = {
  vegan: ["Butter", "Cream", "Bacon", "Parmesan", "Ghee"],
  vegetarian: ["Bacon"],
  keto: ["Rice", "Basmati rice", "Pasta", "Flour"],
  none: []
};
const TIME_RANGES = { quick: [15, 20], medium: [25, 45], elaborate: [50, 75] };
const DIFFICULTY_SEQUENCE = {
  quick: ["easy", "easy", "medium"],
  medium: ["easy", "medium", "medium"],
  elaborate: ["medium", "hard", "hard"]
};

function capitalize(word) { return word.charAt(0).toUpperCase() + word.slice(1); }
function pickRandom(items) { return items[Math.floor(Math.random() * items.length)]; }
function gramsFor(servings) { return 80 + servings * 40; }
function dietSafeStaples(cuisine, diet) {
  const excluded = DIET_EXCLUDED_STAPLES[diet] || [];
  return CUISINE_PRESETS[cuisine].staples.filter(function (s) { return excluded.indexOf(s) === -1; });
}

const options = $node["Validate Request Payload"].json.body;

function buildTitle(index) {
  const templates = CUISINE_PRESETS[options.cuisineStyle].nameTemplates;
  const template = templates[index % templates.length];
  const lead = capitalize(options.ingredients[0] || "Vegetables");
  return template.replace("%s", lead);
}
function buildDescription(title) {
  const spice = pickRandom(CUISINE_PRESETS[options.cuisineStyle].spices);
  return title + ", finished with " + spice + " \u2013 quickly prepared from your ingredients.";
}
function scaleIngredients() {
  const grams = gramsFor(options.servings);
  return options.ingredients.map(function (item) { return grams + " g " + item; });
}
function buildMissingIngredients() {
  const have = options.ingredients.map(function (i) { return i.toLowerCase(); });
  const candidates = dietSafeStaples(options.cuisineStyle, options.diet);
  return candidates.filter(function (s) { return have.indexOf(s.toLowerCase()) === -1; }).slice(0, 3);
}
function stepTexts(missing) {
  const spice = pickRandom(CUISINE_PRESETS[options.cuisineStyle].spices);
  const main = options.ingredients.slice(0, 3).join(", ") || "the ingredients";
  return [
    "Wash and prepare " + main + ".",
    missing.length ? ("Get " + missing.join(", ") + " ready.") : "Weigh out all ingredients.",
    "Heat a pan or pot and season with " + spice + ".",
    "Add the ingredients one by one and cook while stirring.",
    "Season to taste and plate for " + options.servings + " servings."
  ];
}
function buildSteps(missing) {
  const texts = stepTexts(missing);
  return texts.map(function (instruction, i) {
    return { instruction: instruction, assignedTo: (i % options.helpers) + 1, isParallel: options.helpers > 1 && i > 0 && i % 2 === 1 };
  });
}
function pickCookingTime(index) {
  const range = TIME_RANGES[options.timeCategory];
  const step = Math.round(((range[1] - range[0]) / 2) * index);
  return range[0] + step;
}
function buildNutrition() {
  const base = { caloriesPerServing: 520, proteinGrams: 28, carbsGrams: 55, fatGrams: 18 };
  if (options.diet === "keto") return Object.assign({}, base, { carbsGrams: 12, fatGrams: 38 });
  if (options.diet === "vegan") return Object.assign({}, base, { proteinGrams: 18, fatGrams: 14 });
  return base;
}
function buildRecipe(index) {
  const title = buildTitle(index);
  const missingIngredients = buildMissingIngredients();
  return {
    title: title,
    description: buildDescription(title),
    ingredients: scaleIngredients(),
    missingIngredients: missingIngredients,
    steps: buildSteps(missingIngredients),
    difficulty: DIFFICULTY_SEQUENCE[options.timeCategory][index],
    cookingTimeMinutes: pickCookingTime(index),
    servings: options.servings,
    cuisineStyle: options.cuisineStyle,
    nutrition: buildNutrition()
  };
}

const recipes = [0, 1, 2].map(buildRecipe);
const counts = $node["Parse Quota Reservation"].json;

